import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, mix, float, fract, sin, dot, add, mul, sub } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  const root = new Group();
  root.name = 'kinetic-hero-headline';

  const colors = (config.intent && config.intent.visualSpec && config.intent.visualSpec.colors) || {};
  const cBg = colors.background || '#0b0b10';
  const cBg2 = (colors.gradientStops && colors.gradientStops[1] && colors.gradientStops[1].hex) || '#13131a';
  const cPaper = colors.paper || '#e8ecf2';
  const cAccent = colors.accent || '#ff2a38';

  const disposables = [];
  const timelines = [];
  const primHandles = [];

  // ---------------------------------------------------------------
  // BACKDROP: 7 x 5.5 engineered vertical gradient + 1.5% mono grain
  // ---------------------------------------------------------------
  const bgGeo = new PlaneGeometry(7, 5.5);
  const bgMat = new MeshBasicNodeMaterial();
  {
    const c0 = vec3(new Color(cBg).r, new Color(cBg).g, new Color(cBg).b);
    const c1 = vec3(new Color(cBg2).r, new Color(cBg2).g, new Color(cBg2).b);
    const grad = mix(c0, c1, uv().y);
    const n = fract(mul(sin(dot(mul(uv(), vec2(127.1, 311.7)), vec2(1.0, 1.0))), float(43758.5453)));
    const grain = mul(sub(n, float(0.5)), float(0.03));
    bgMat.colorNode = add(grad, grain);
  }
  const backdrop = new Mesh(bgGeo, bgMat);
  backdrop.position.set(0, 0, -1.5);
  root.add(backdrop);
  disposables.push(bgGeo, bgMat);

  // ---------------------------------------------------------------
  // TEXT CONTENT (verbatim from spec items)
  // ---------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let captionStr = 'NOVA ATELIER / CALIBRE PROGRAM';
  let heroStr = 'TIME, MACHINED.';
  let subheadStr = 'Every calibre begins as a solid billet.';
  for (const item of items) {
    if (item.role === 'caption') captionStr = item.text;
    else if (item.role === 'hero') heroStr = item.text;
    else if (item.role === 'subhead') subheadStr = item.text;
  }

  // Caption kicker at y = 1.15
  const caption = ctx.fontAtlas.createText(String(captionStr), {
    fontSize: 18,
    color: cAccent,
    align: 'center',
    letterSpacingPx: 2.2,
  });
  caption.position.set(0, 1.15, 0.05);
  root.add(caption);

  // ---------------------------------------------------------------
  // HERO: per-word dimensional type, front-to-back z parallax
  // ---------------------------------------------------------------
  const heroGroup = new Group();
  heroGroup.position.set(0, 0.4, 0);
  root.add(heroGroup);

  const words = String(heroStr).split(' ').filter((w) => w.length > 0);
  const EM = 0.62; // hero em height in scene units
  const CHAR_W = EM * 0.55;
  const GAP = 0.3;
  const zSteps = words.length === 3 ? [0.12, 0.0, -0.12] : words.length === 2 ? [0.12, -0.12] : [0.0];

  const widths = words.map((w) => w.length * CHAR_W);
  const totalW = widths.reduce((a, b) => a + b, 0) + GAP * (words.length - 1);

  const wordObjs = [];
  let cursor = -totalW / 2;
  words.forEach((word, i) => {
    const wObj = ctx.fontAtlas.createText(String(word), {
      fontSize: 124,
      color: cPaper,
      align: 'center',
      letterSpacingPx: -1.2,
    });
    const cx = cursor + widths[i] / 2;
    wObj.position.set(cx, 0, zSteps[Math.min(i, zSteps.length - 1)] || 0);
    heroGroup.add(wObj);
    wordObjs.push(wObj);
    cursor += widths[i] + GAP;
  });

  // ---------------------------------------------------------------
  // ACCENT UNDERLINE: 2.6 x 0.045, emissive 1.2, left-anchored reveal
  // ---------------------------------------------------------------
  const ruleGeo = new PlaneGeometry(2.6, 0.045);
  ruleGeo.translate(1.3, 0, 0); // anchor left edge at origin
  const ruleMat = new MeshStandardNodeMaterial({
    color: new Color(cAccent),
    emissive: new Color(cAccent),
    emissiveIntensity: 1.2,
    roughness: 0.6,
    metalness: 0.1,
  });
  const rule = new Mesh(ruleGeo, ruleMat);
  rule.position.set(-1.3, -0.05, 0.02);
  rule.scale.x = 0.0001;
  root.add(rule);
  disposables.push(ruleGeo, ruleMat);

  // ---------------------------------------------------------------
  // SUBHEAD at y = -0.65 (fades up)
  // ---------------------------------------------------------------
  const subhead = ctx.fontAtlas.createText(String(subheadStr), {
    fontSize: 40,
    color: cPaper,
    align: 'center',
    letterSpacingPx: 0.8,
  });
  subhead.position.set(0, -0.85, 0.02); // starts +0.2 below target
  root.add(subhead);

  const setOpacity = (obj, v) => {
    obj.traverse((child) => {
      if (child.material) {
        child.material.transparent = true;
        child.material.opacity = v;
      }
    });
  };
  setOpacity(subhead, 0);
  setOpacity(caption, 0);

  // ---------------------------------------------------------------
  // CINEMATIC PRIMITIVES (from config, applied via ctx.primitives)
  // ---------------------------------------------------------------
  const prims = config.cinematicPrimitives ?? [];
  for (const primitive of prims) {
    const fn = ctx.primitives[primitive.name];
    if (fn) {
      const handle = fn(heroGroup, primitive.params || {});
      if (handle) primHandles.push(handle);
    }
  }

  // ---------------------------------------------------------------
  // MOTION: word rise + weighted settle + underline + subhead
  // ---------------------------------------------------------------
  const glyphCount = String(heroStr).replace(/\s/g, '').length;
  const lastGlyphLand = (glyphCount - 1) * 0.06 + 0.7; // 60ms stagger, 700ms per glyph

  const tl = gsap.timeline();
  timelines.push(tl);

  // caption fade-up first
  const capState = { o: 0 };
  tl.to(capState, {
    o: 1,
    duration: 0.5,
    ease: 'power2.out',
    onUpdate: () => setOpacity(caption, capState.o),
  }, 0);
  tl.from(caption.position, { y: '+=0.2', duration: 0.5, ease: 'power2.out' }, 0);

  // per-word kinetic rise (staggered left to right) complementing kinetic-text primitive
  wordObjs.forEach((wObj, i) => {
    const t0 = 0.1 + i * 0.06;
    tl.from(wObj.position, { y: '+=0.35', duration: 0.7, ease: 'power3.out' }, t0);
    const st = { o: 0 };
    tl.to(st, {
      o: 1,
      duration: 0.7,
      ease: 'power3.out',
      onUpdate: () => setOpacity(wObj, st.o),
    }, t0);
  });

  // group weighted settle triggered by final glyph landing
  heroGroup.scale.setScalar(1.04);
  tl.to(heroGroup.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'power4.out',
  }, lastGlyphLand);

  // underline reveal, left-anchored, 120ms after last glyph lands
  tl.to(rule.scale, {
    x: 1,
    duration: 0.5,
    ease: 'power2.out',
  }, lastGlyphLand + 0.12);

  // subhead fade-up
  const subState = { o: 0 };
  tl.to(subhead.position, { y: -0.65, duration: 0.5, ease: 'power2.out' }, lastGlyphLand + 0.35);
  tl.to(subState, {
    o: 1,
    duration: 0.5,
    ease: 'power2.out',
    onUpdate: () => setOpacity(subhead, subState.o),
  }, lastGlyphLand + 0.35);

  // idle: single slow breathing on hero group (<= 2%)
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true, delay: lastGlyphLand + 1.2 });
  idleTl.to(heroGroup.scale, { x: 1.015, y: 1.015, z: 1.015, duration: 3.4, ease: 'sine.inOut' });
  timelines.push(idleTl);

  // ---------------------------------------------------------------
  // handlers + cleanup
  // ---------------------------------------------------------------
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    primHandles.forEach((h) => { if (h && h.cleanup) h.cleanup(); });
    disposables.forEach((d) => { if (d && d.dispose) d.dispose(); });
    root.traverse((child) => {
      if (child.geometry && child.geometry.dispose) child.geometry.dispose();
      if (child.material && child.material.dispose) child.material.dispose();
    });
  };

  return root;
}
